package store

import (
	"crypto/sha256"
	"database/sql"
	"encoding/hex"
	"time"
)

// sessionKey is what the sessions table keeps for a token: its SHA-256, so
// a copy of the database doesn't hold cookies that sign in. Rows from
// before, which kept tokens as they were, are dropped when the store opens.
func sessionKey(token string) string {
	sum := sha256.Sum256([]byte(token))
	return "sha256:" + hex.EncodeToString(sum[:])
}

// CreateSession persists a new login session token. token is expected to
// already be a cryptographically random, unguessable value generated by the
// caller — the store only ever compares tokens for exact equality, never
// derives or validates their entropy.
func (s *Store) CreateSession(token string, expiresAt time.Time) error {
	s.accessMu.Lock()
	defer s.accessMu.Unlock()
	// Sessions that ran out go now: one never looked up again would stay.
	// The times are compared as text, which orders fractions of a second
	// loosely: a second's margin keeps every one deleted already out.
	if err := s.exec(`DELETE FROM sessions WHERE expires_at < ?`, rfc3339(time.Now().Add(-time.Second))); err != nil {
		return err
	}
	return s.exec(`INSERT INTO sessions(token,created_at,expires_at) VALUES(?,?,?)`, sessionKey(token), rfc3339(time.Now()), rfc3339(expiresAt))
}

// SessionValid reports whether token names a session that exists and has not
// yet expired. An expired session is lazily deleted here rather than left
// for a background sweep, since checking validity already required reading
// its row.
func (s *Store) SessionValid(token string) (bool, error) {
	s.accessMu.Lock()
	defer s.accessMu.Unlock()
	var raw string
	err := s.q.QueryRow(`SELECT expires_at FROM sessions WHERE token=?`, sessionKey(token)).Scan(&raw)
	if err == sql.ErrNoRows {
		return false, nil
	}
	if err != nil {
		return false, err
	}
	expiresAt, err := time.Parse(time.RFC3339Nano, raw)
	if err != nil {
		return false, nil
	}
	if !time.Now().UTC().Before(expiresAt) {
		return false, s.deleteSession(token)
	}
	return true, nil
}

// DeleteSession removes one session, e.g. on logout.
func (s *Store) DeleteSession(token string) error {
	s.accessMu.Lock()
	defer s.accessMu.Unlock()
	return s.deleteSession(token)
}

func (s *Store) deleteSession(token string) error {
	return s.exec(`DELETE FROM sessions WHERE token=?`, sessionKey(token))
}

// DeleteAllSessions signs every session out at once — used after a password
// change so a credential rotation actually revokes access from any other
// still-logged-in browser instead of only the one that made the change.
func (s *Store) DeleteAllSessions() error {
	s.accessMu.Lock()
	defer s.accessMu.Unlock()
	return s.exec(`DELETE FROM sessions`)
}
